import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/AccumulateType.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>

template <typename scalar_t, typename acc_t>
__global__ void conv_transpose3d_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int64_t batch,
    int64_t in_channels,
    int64_t out_channels,
    int64_t in_depth,
    int64_t in_height,
    int64_t in_width,
    int64_t out_depth,
    int64_t out_height,
    int64_t out_width,
    int64_t kernel_size,
    int64_t stride,
    int64_t padding,
    int64_t groups,
    bool has_bias
) {
    constexpr int TILE_D = 2;
    constexpr int TILE_H = 4;
    constexpr int TILE_W = 4;
    constexpr int OC_TILE = 8;
    const int64_t out_channels_per_group = out_channels / groups;
    const int64_t in_channels_per_group = in_channels / groups;
    const int64_t kernel_volume = kernel_size * kernel_size * kernel_size;
    const int64_t tiles_h = (out_height + TILE_H - 1) / TILE_H;
    const int64_t tiles_w = (out_width + TILE_W - 1) / TILE_W;
    const int64_t tile_index = static_cast<int64_t>(blockIdx.x);
    const int64_t tile_d = tile_index / (tiles_h * tiles_w);
    const int64_t tile_rem = tile_index % (tiles_h * tiles_w);
    const int64_t tile_h = tile_rem / tiles_w;
    const int64_t tile_w = tile_rem % tiles_w;
    const int64_t n = static_cast<int64_t>(blockIdx.z);
    const int64_t oc_tiles_per_group =
        (out_channels_per_group + OC_TILE - 1) / OC_TILE;
    const int64_t group_tile = static_cast<int64_t>(blockIdx.y);
    const int64_t group = group_tile / oc_tiles_per_group;
    const int64_t oc_tile = group_tile % oc_tiles_per_group;
    const int64_t oc_local = oc_tile * OC_TILE + (threadIdx.x % OC_TILE);
    const int64_t oc = group * out_channels_per_group + oc_local;
    const bool active_oc = oc < out_channels;

    const int64_t od_start = tile_d * TILE_D;
    const int64_t oh_start = tile_h * TILE_H;
    const int64_t ow_start = tile_w * TILE_W;

    const int64_t od_end = std::min<int64_t>(out_depth, od_start + TILE_D);
    const int64_t oh_end = std::min<int64_t>(out_height, oh_start + TILE_H);
    const int64_t ow_end = std::min<int64_t>(out_width, ow_start + TILE_W);

    const int64_t d_num = od_start + padding - (kernel_size - 1);
    const int64_t h_num = oh_start + padding - (kernel_size - 1);
    const int64_t w_num = ow_start + padding - (kernel_size - 1);

    const int64_t id_start = std::max<int64_t>(0, d_num / stride);
    const int64_t ih_start = std::max<int64_t>(0, h_num / stride);
    const int64_t iw_start = std::max<int64_t>(0, w_num / stride);

    const int64_t id_end = std::min<int64_t>(
        in_depth, (od_end - 1 + padding) / stride + 1);
    const int64_t ih_end = std::min<int64_t>(
        in_height, (oh_end - 1 + padding) / stride + 1);
    const int64_t iw_end = std::min<int64_t>(
        in_width, (ow_end - 1 + padding) / stride + 1);

    const int64_t shared_height = TILE_H + kernel_size - 1;
    const int64_t shared_width = TILE_W + kernel_size - 1;

    extern __shared__ unsigned char shared_mem[];
    scalar_t* shared_input = reinterpret_cast<scalar_t*>(shared_mem);

    const int tid = threadIdx.x;
    const int spatial_tid = tid / OC_TILE;
    const int local_w = spatial_tid % TILE_W;
    const int local_h = (spatial_tid / TILE_W) % TILE_H;
    const int local_d = spatial_tid / (TILE_W * TILE_H);
    acc_t sum = (has_bias && active_oc) ?
        static_cast<acc_t>(bias[oc]) : acc_t(0);

    for (int64_t ic_local = 0; ic_local < in_channels_per_group; ++ic_local) {
        const int64_t ic = group * in_channels_per_group + ic_local;
        const int64_t shared_depth = std::max<int64_t>(0, id_end - id_start);
        const int64_t shared_h = std::max<int64_t>(0, ih_end - ih_start);
        const int64_t shared_w = std::max<int64_t>(0, iw_end - iw_start);
        const int64_t shared_count = shared_depth * shared_h * shared_w;

        for (int64_t q = tid; q < shared_count; q += blockDim.x) {
            int64_t v = q;
            const int64_t iw = v % shared_w;
            v /= shared_w;
            const int64_t ih = v % shared_h;
            v /= shared_h;
            const int64_t id = v;

            const int64_t input_d = id_start + id;
            const int64_t input_h = ih_start + ih;
            const int64_t input_w = iw_start + iw;
            const int64_t x_offset =
                (((n * in_channels + ic) * in_depth + input_d) *
                     in_height + input_h) *
                    in_width + input_w;
            const int64_t smem_offset =
                (id * shared_height + ih) * shared_width + iw;
            shared_input[smem_offset] = x[x_offset];
        }
        __syncthreads();

        const int64_t od = od_start + local_d;
        const int64_t oh = oh_start + local_h;
        const int64_t ow = ow_start + local_w;

        if (active_oc && od < out_depth && oh < out_height && ow < out_width) {
            for (int64_t kd = 0; kd < kernel_size; ++kd) {
                const int64_t td = od + padding - kd;
                if (td < 0 || td % stride != 0) {
                    continue;
                }
                const int64_t id = td / stride;
                if (id >= in_depth || id < id_start || id >= id_end) {
                    continue;
                }

                for (int64_t kh = 0; kh < kernel_size; ++kh) {
                    const int64_t th = oh + padding - kh;
                    if (th < 0 || th % stride != 0) {
                        continue;
                    }
                    const int64_t ih = th / stride;
                    if (ih >= in_height || ih < ih_start || ih >= ih_end) {
                        continue;
                    }

